let LANG='ar';
function t(k,...a){let s=(I18N[LANG]&&I18N[LANG][k]);if(s==null)s=I18N.ar[k]??k;return s.replace(/\{(\d)\}/g,(_,i)=>a[i]??'')}
const L=()=>LOC[LANG];
function applyI18n(){document.documentElement.lang=LANG;document.documentElement.dir=LANG==='ar'?'rtl':'ltr';document.title=t('app');{const hb=document.getElementById('helpBtn');if(hb)hb.title=t('tour.again')}
  $$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$$('[data-i18n-ph]').forEach(e=>e.placeholder=t(e.dataset.i18nPh));
  $('#logo').textContent=t('app');$('#logo').dataset.t=t('app');}

const DEF_CAT={study:{ar:'دراسة',en:'Study'},course:{ar:'دورات',en:'Courses'},gym:{ar:'تمرين',en:'Workout'},work:{ar:'عمل',en:'Work'},quran:{ar:'قرآن',en:'Quran'},'q-hifz':{ar:'حفظ',en:'Memorization'},'q-review':{ar:'مراجعة',en:'Review'},'q-wird':{ar:'ورد',en:'Wird'},'q-tilawa':{ar:'تلاوة عشوائية',en:'Free recitation'}};
function kidName(c){const d=DEF_CAT[c.id];if(d&&(c.name===d.ar||c.name===d.en))return d[LANG];return c.name}
function catName(c){if(c&&c.parent){const p=S.settings.categories.find(x=>x.id===c.parent);if(p)return kidName(p)+' · '+kidName(c)}return kidName(c)}
function boardName(b){return (b.name==='ملاحظات'||b.name==='Notes')?t('board.def'):b.name}

