const hsl=(h,s,l)=>`hsl(${h} ${s}% ${l}%)`;
function surfaces(mode,h){
  if(mode==='light')return{bg:hsl(h,22,95.5),panel:'#ffffff',panel2:hsl(h,20,93.5),line:hsl(h,14,86),text:hsl(h,18,12),muted:hsl(h,8,44)};
  if(mode==='black')return{bg:'#000000',panel:hsl(h,8,4.5),panel2:hsl(h,7,8),line:hsl(h,6,13),text:'#ececec',muted:hsl(h,5,53)};
  return{bg:hsl(h,16,6.5),panel:hsl(h,14,9.5),panel2:hsl(h,12,12.5),line:hsl(h,11,17.5),text:hsl(h,16,92),muted:hsl(h,9,61)}}
